const t=team.t,o=opp.t;
if(t.style==="possession"&&(o.defenseStyle==="pressure"||Number(o.pressing||50)>72)){const control=(avg(team.ps,"pass")+avg(team.ps,"ballControl"))/2;if(control>=70)atk+=.045;else atk-=.075}
