[H,A].forEach(team=>team.club.players.forEach(p=>{if(team.ps.includes(p)){p.apps=(p.apps||0)+1;p.fitness=clamp((p.fitness||75)-(p.starter?10:4),10,100);if(chance(.009))p.injury=1+Math.floor(Math.random()*3)}}));
