function train(){
const c=ccur();let trained=0,recovered=0;
const plans={balanced:["pass","ballControl","stamina"],attack:["finishing","shoot","dribbling"],defense:["tackling","marking","positioning"],midfield:["pass","vision","throughPass"],goalkeeper:["goalkeeping","reaction","positioning"]};
c.players.forEach(p=>{
if(state.training==="fitness"){p.fitness=clamp((p.fitness||70)+14,0,100);p.injury=Math.max(0,(p.injury||0)-1);recovered++;return}
if(p.fitness<20){p.fitness=clamp(p.fitness+5,0,100);return}
const keys=plans[state.training]||plans.balanced,age=Number(p.age)||24,potential=Number(p.potential)||calculateOverall(p),facility=(c.facilities||{}).training||1;
const ageFactor=age<=20?1.2:age<=24?1:age<=29?.75:age<=33?.45:.25;
const gain=clamp(Math.round((.35+ageFactor*.5+Math.max(0,potential-calculateOverall(p))/180+(facility-1)*.08)*(Math.random()<.15?2:1)),1,2);
keys.forEach((k,i)=>{if(p[k]<110&&(i===0||Math.random()<.55))p[k]=clamp(p[k]+gain,10,110)});
p.fitness=clamp((p.fitness||80)-6,0,100);p.defense=Math.round((p.tackling+p.marking+p.positioning)/3);p.rating=calculateOverall(p);p.value=playerValue(p);trained++;
});
log("جلسه تمرینی "+({balanced:"متعادل",fitness:"ریکاوری و آمادگی",attack:"هجومی",defense:"دفاعی",midfield:"ویژه هافبک‌ها",goalkeeper:"ویژه دروازه‌بان‌ها"}[state.training]||"تیمی")+" اجرا شد؛ "+trained+" بازیکن تمرین کردند","تمرین");
commit(state.training==="fitness"?"ریکاوری انجام شد؛ آمادگی بازیکنان افزایش یافت.":"تمرین اجرا شد؛ ویژگی‌های واقعی بازیکنان به‌روزرسانی شد.")
}
function individual(id){const p=getp(id);if(!p)return;state.profilePlayerId=id;active="playerProfile";render();window.scrollTo({top:0,behavior:"smooth"})}
function trainIndividualSkill(id,key){
const p=ccur().players.find(x=>x.id===id);if(!p||!TRAINABLE_SKILLS.includes(key)){toast("این تمرین در دسترس نیست.");return}
if(p.fitness<12){toast("آمادگی کافی نیست؛ ابتدا ریکاوری کن.");return}
p.trainingSessions=p.trainingSessions||{season:state.season,week:state.week,count:0};
if(p.trainingSessions.season!==state.season||p.trainingSessions.week!==state.week)p.trainingSessions={season:state.season,week:state.week,count:0};
if(p.trainingSessions.count>=3){toast("سهمیه تمرین این بازیکن در این هفته تمام شده است.");return}
const facility=(ccur().facilities||{}).training||1,age=Number(p.age)||24,potential=Number(p.potential)||calculateOverall(p);
const ageFactor=age<=20?1.25:age<=24?1.05:age<=29?.8:age<=33?.55:.3;
const talentFactor=.65+Math.max(0,potential-calculateOverall(p))/100;
const gain=clamp(Math.round(.65+ageFactor*.65+talentFactor*.4+(facility-1)*.08),1,3);
if(p[key]>=110){toast("این ویژگی به حداکثر ۱۱۰ رسیده است.");return}
p[key]=clamp(p[key]+gain,10,110);p.fitness=clamp((p.fitness||80)-7,0,100);p.trainingSessions.count++;
p.defense=Math.round((p.tackling+p.marking+p.positioning)/3);p.rating=calculateOverall(p);p.value=playerValue(p);
log("تمرین اختصاصی "+p.name+" · "+SKILL_LABELS[key]+" +"+num(gain),"تمرین");
commit("تمرین "+SKILL_LABELS[key]+" انجام شد؛ پیشرفت "+num(gain)+" واحد.")
}
function predict(id){let m=state.fixtures.find(x=>x.id===id);if(!m||m.played){toast("این مسابقه قابل پیش‌بینی نیست.");return}if(state.predictions[id]){toast("قبلاً پیش‌بینی ثبت شده است.");return}let h=Number($("#ph-"+id).value),a=Number($("#pa-"+id).value);if(!Number.isInteger(h)||!Number.isInteger(a)||h<0||a<0||h>9||a>9){toast("گل‌ها باید عدد صحیح بین صفر تا ۹ باشند.");return}state.predictions[id]={home:h,away:a};log("پیش‌بینی رایگان ثبت شد: "+h+" - "+a,"پیش‌بینی");commit("پیش‌بینی رایگان ثبت شد.")}
