function filterMarket(){let q=$("#ms")?.value||"",pos=$("#mp")?.value||"",sort=$("#msort")?.value||"rating",a=state.market.filter(p=>p.name.includes(q)&&(!pos||p.position===pos)&&p.clubId!==state.clubId);a.sort((x,y)=>sort==="asking"?x.asking-y.asking:sort==="age"?x.age-y.age:y.rating-x.rating);$("#market-grid").innerHTML=a.length?a.map(p=>card(p,"market")).join(""):'<div class="empty">بازیکنی پیدا نشد.</div>'}
let dragPlayer=null,dragStart=null;
document.addEventListener("pointerdown",e=>{const el=e.target.closest("[data-pitch-player],[data-bench-player]");if(!el)return;dragPlayer=el.dataset.pitchPlayer||el.dataset.benchPlayer;dragStart={x:e.clientX,y:e.clientY,from:el.dataset.pitchPlayer?"pitch":"bench"};el.classList.add("dragging");if(el.setPointerCapture)try{el.setPointerCapture(e.pointerId)}catch(_){}});
document.addEventListener("pointerup",e=>{if(!dragPlayer||!dragStart)return;const id=dragPlayer,from=dragStart.from,dx=e.clientX-dragStart.x,dy=e.clientY-dragStart.y;document.querySelectorAll(".dragging").forEach(x=>x.classList.remove("dragging"));dragPlayer=null;dragStart=null;if(Math.abs(dx)+Math.abs(dy)<8)return;const c=ccur(),p=c.players.find(x=>x.id===id);if(!p)return;const pitch=$("#football-pitch"),bench=$("#bench-list"),r=pitch?.getBoundingClientRect();if(r&&e.clientX>=r.left&&e.clientX<=r.right&&e.clientY>=r.top&&e.clientY<=r.bottom){const x=clamp((e.clientX-r.left)/r.width*100,5,95),y=clamp((e.clientY-r.top)/r.height*100,6,94);if(from==="bench"){const starters=c.players.filter(x=>x.starter);if(!starters.length)return toast("ابتدا یک بازیکن را فیکس کن.");let nearest=starters.sort((a,b)=>{const ax=Number.isFinite(a.posX)?a.posX:50,ay=Number.isFinite(a.posY)?a.posY:50,bx=Number.isFinite(b.posX)?b.posX:50,by=Number.isFinite(b.posY)?b.posY:50;return Math.hypot(ax-x,ay-y)-Math.hypot(bx-x,by-y)})[0];nearest.starter=false;delete nearest.posX;delete nearest.posY;p.starter=true;p.posX=x;p.posY=y}else{p.posX=x;p.posY=y}commit("جای بازیکن در زمین ذخیره شد.");return}if(from==="pitch"&&bench&&e.clientX>=bench.getBoundingClientRect().left&&e.clientX<=bench.getBoundingClientRect().right&&e.clientY>=bench.getBoundingClientRect().top&&e.clientY<=bench.getBoundingClientRect().bottom){p.starter=false;delete p.posX;delete p.posY;commit("بازیکن به نیمکت منتقل شد.")}});
